PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (     user_id INTEGER PRIMARY KEY,     username TEXT,     first_name TEXT,     title TEXT DEFAULT '',     intro TEXT DEFAULT '',     balance INTEGER DEFAULT 200,     total_earned INTEGER DEFAULT 0,     total_spent INTEGER DEFAULT 0,     kills INTEGER DEFAULT 0,     robs INTEGER DEFAULT 0,     wins INTEGER DEFAULT 0,     losses INTEGER DEFAULT 0,     highest_points INTEGER DEFAULT 0,     streak INTEGER DEFAULT 0,     reputation INTEGER DEFAULT 0,     status TEXT DEFAULT 'alive',     protected_until INTEGER DEFAULT 0,     dead_until INTEGER DEFAULT 0,     created_at INTEGER,     updated_at INTEGER , is_bot INTEGER DEFAULT 0);
CREATE TABLE groups (     chat_id INTEGER PRIMARY KEY,     title TEXT,     save_mode INTEGER DEFAULT 0,     web_enabled INTEGER DEFAULT 0,     economy_enabled INTEGER DEFAULT 1,     rules TEXT DEFAULT '',     welcome_message TEXT DEFAULT '',     goodbye_message TEXT DEFAULT '',     created_at INTEGER , username TEXT, type TEXT, updated_at INTEGER);
CREATE TABLE inventory (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER,     item_id INTEGER,     quantity INTEGER DEFAULT 1 );
CREATE TABLE shop_items (     item_id INTEGER PRIMARY KEY,     name TEXT,     emoji TEXT,     price INTEGER );
CREATE TABLE transactions (     id INTEGER PRIMARY KEY AUTOINCREMENT,     from_user INTEGER,     to_user INTEGER,     amount INTEGER,     tax INTEGER,     type TEXT,     created_at INTEGER , sender_id INTEGER, receiver_id INTEGER);
CREATE TABLE warnings (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER,     admin_id INTEGER,     chat_id INTEGER,     reason TEXT,     created_at INTEGER );
CREATE TABLE messages (     message_id INTEGER,     chat_id INTEGER,     user_id INTEGER,     reply_to INTEGER,     text TEXT,     created_at INTEGER,     expires_at INTEGER );
CREATE TABLE antispam (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     target_user INTEGER,     admin_id INTEGER,     enabled INTEGER DEFAULT 1,     created_at INTEGER );
CREATE TABLE card_matches (     match_id TEXT PRIMARY KEY,     chat_id INTEGER,     bet_amount INTEGER,     target_sum INTEGER,     status TEXT,     created_at INTEGER , expires_at INTEGER);
CREATE TABLE card_players (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     user_id INTEGER,     score REAL DEFAULT 0,     strikes INTEGER DEFAULT 0,     prediction INTEGER,     card_a INTEGER,     card_b INTEGER,     card_c INTEGER,     card_d INTEGER,     flipped_a INTEGER DEFAULT 0,     flipped_b INTEGER DEFAULT 0,     flipped_c INTEGER DEFAULT 0,     flipped_d INTEGER DEFAULT 0 );
CREATE TABLE mod_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     admin_id INTEGER,     target_id INTEGER,     action TEXT,     reason TEXT,     created_at INTEGER );
CREATE TABLE treasury (     id INTEGER PRIMARY KEY,     balance INTEGER DEFAULT 0 );
CREATE TABLE channels (     channel_id INTEGER PRIMARY KEY,     title TEXT,     auto_react INTEGER DEFAULT 0,     auto_post INTEGER DEFAULT 0,     created_at INTEGER );
CREATE TABLE ai_memory (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     user_id INTEGER,     message TEXT,     created_at INTEGER,     expires_at INTEGER );
CREATE TABLE card_rounds (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     round_number INTEGER,     finished INTEGER DEFAULT 0,     created_at INTEGER );
CREATE TABLE card_moves (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     round_number INTEGER,     user_id INTEGER,     card_used TEXT,     card_value INTEGER,     auto_flip INTEGER DEFAULT 0,     created_at INTEGER );
CREATE TABLE card_predictions (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     user_id INTEGER,     predicted_round INTEGER,     prediction_correct INTEGER DEFAULT 0 );
CREATE TABLE card_results (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     user_id INTEGER,     final_points REAL,     placement INTEGER,     reward INTEGER,     winner INTEGER DEFAULT 0 );
CREATE TABLE card_history (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER,     match_id TEXT,     bet_amount INTEGER,     points REAL,     placement INTEGER,     profit INTEGER,     created_at INTEGER );
CREATE TABLE card_leaderboard (     user_id INTEGER PRIMARY KEY,     matches_played INTEGER DEFAULT 0,     matches_won INTEGER DEFAULT 0,     total_profit INTEGER DEFAULT 0,     total_points REAL DEFAULT 0,     highest_score REAL DEFAULT 0 );
CREATE TABLE card_achievements (     user_id INTEGER PRIMARY KEY,     perfect_wins INTEGER DEFAULT 0,     tournaments_won INTEGER DEFAULT 0,     highest_win INTEGER DEFAULT 0 );
CREATE TABLE active_matches (     match_id TEXT PRIMARY KEY,     current_round INTEGER,     current_turn INTEGER,     waiting_for INTEGER,     expires_at INTEGER );
CREATE TABLE card_strikes (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     user_id INTEGER,     strike_number INTEGER,     round_number INTEGER,     created_at INTEGER );
CREATE TABLE card_taxes (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     total_pool INTEGER,     tax_amount INTEGER,     distributed_amount INTEGER,     created_at INTEGER );
CREATE TABLE locks (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER NOT NULL,     lock_type TEXT NOT NULL,     enabled INTEGER DEFAULT 1,     updated_by INTEGER,     updated_at INTEGER );
CREATE TABLE reports (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     reporter_id INTEGER,     target_id INTEGER,     reason TEXT,     status TEXT DEFAULT 'open',     created_at INTEGER );
CREATE TABLE welcome_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 1,     message TEXT,     media_url TEXT,     updated_at INTEGER );
CREATE TABLE antilink_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 0,     action TEXT DEFAULT 'delete' );
CREATE TABLE antiflood_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 0,     max_messages INTEGER DEFAULT 5,     seconds_window INTEGER DEFAULT 10,     action TEXT DEFAULT 'mute' );
CREATE TABLE antiraid_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 0,     join_limit INTEGER DEFAULT 10,     seconds_window INTEGER DEFAULT 60,     action TEXT DEFAULT 'lock' );
CREATE TABLE invite_rewards (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     inviter_id INTEGER,     member_count INTEGER,     reward INTEGER,     claimed INTEGER DEFAULT 0,     created_at INTEGER );
CREATE TABLE ai_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 1,     web_enabled INTEGER DEFAULT 0,     inactivity_enabled INTEGER DEFAULT 1,     inactivity_minutes INTEGER DEFAULT 90 );
CREATE TABLE web_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 0,     updated_by INTEGER,     updated_at INTEGER );
CREATE TABLE channel_reactions (     channel_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 1,     reaction_type TEXT DEFAULT '🤣',     updated_at INTEGER );
CREATE TABLE channel_posts (     id INTEGER PRIMARY KEY AUTOINCREMENT,     channel_id INTEGER,     message_id INTEGER,     views INTEGER DEFAULT 0,     reactions INTEGER DEFAULT 0,     created_at INTEGER );
CREATE TABLE scheduled_posts (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     content TEXT,     media_url TEXT,     scheduled_for INTEGER,     sent INTEGER DEFAULT 0,     created_by INTEGER , send_at INTEGER);
CREATE TABLE broadcasts (     id INTEGER PRIMARY KEY AUTOINCREMENT,     source_chat INTEGER,     target_chat INTEGER,     enabled INTEGER DEFAULT 1 );
CREATE TABLE economy_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 1,     rob_enabled INTEGER DEFAULT 1,     kill_enabled INTEGER DEFAULT 1,     card_enabled INTEGER DEFAULT 1 );
CREATE TABLE treasury_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,     source_type TEXT,     amount INTEGER,     reference_id TEXT,     created_at INTEGER );
CREATE TABLE gif_pool (     id INTEGER PRIMARY KEY AUTOINCREMENT,     command TEXT,     gif_url TEXT );
CREATE TABLE save_settings (     chat_id INTEGER PRIMARY KEY,     enabled INTEGER DEFAULT 0,     enabled_by INTEGER,     updated_at INTEGER );
CREATE TABLE user_settings (     user_id INTEGER PRIMARY KEY,     notifications INTEGER DEFAULT 1,     dm_cards INTEGER DEFAULT 1,     allow_gifts INTEGER DEFAULT 1,     language TEXT DEFAULT 'en',     updated_at INTEGER );
CREATE TABLE cooldowns (     user_id INTEGER,     command TEXT,     expires_at INTEGER,     PRIMARY KEY(user_id, command) );
CREATE TABLE badges (     badge_id INTEGER PRIMARY KEY,     name TEXT,     description TEXT,     emoji TEXT );
CREATE TABLE user_badges (     user_id INTEGER,     badge_id INTEGER,     earned_at INTEGER,     PRIMARY KEY(user_id,badge_id) );
CREATE TABLE group_stats (     chat_id INTEGER PRIMARY KEY,     total_messages INTEGER DEFAULT 0,     total_commands INTEGER DEFAULT 0,     active_users INTEGER DEFAULT 0,     updated_at INTEGER );
CREATE TABLE user_stats (     user_id INTEGER PRIMARY KEY,     total_messages INTEGER DEFAULT 0,     total_commands INTEGER DEFAULT 0,     total_ai_messages INTEGER DEFAULT 0,     updated_at INTEGER );
CREATE TABLE api_cache (     cache_key TEXT PRIMARY KEY,     response TEXT,     expires_at INTEGER );
CREATE TABLE web_history (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER,     query TEXT,     created_at INTEGER );
CREATE TABLE deleted_messages (     id INTEGER PRIMARY KEY AUTOINCREMENT,     chat_id INTEGER,     user_id INTEGER,     message_text TEXT,     deleted_by INTEGER,     deleted_at INTEGER,     expires_at INTEGER );
CREATE TABLE cleanup_queue (     id INTEGER PRIMARY KEY AUTOINCREMENT,     table_name TEXT,     row_id INTEGER,     delete_at INTEGER );
CREATE TABLE bot_config (     config_key TEXT PRIMARY KEY,     config_value TEXT );
CREATE TABLE admin_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,     admin_id INTEGER,     action TEXT,     target_id INTEGER,     chat_id INTEGER,     created_at INTEGER );
CREATE TABLE rate_limits (     user_id INTEGER,     action TEXT,     count INTEGER,     expires_at INTEGER,     PRIMARY KEY(user_id,action) );
CREATE TABLE card_replay (     id INTEGER PRIMARY KEY AUTOINCREMENT,     match_id TEXT,     replay_data TEXT );
CREATE TABLE error_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,     module TEXT,     error TEXT,     created_at INTEGER );
CREATE TABLE audit_logs (     id INTEGER PRIMARY KEY AUTOINCREMENT,     actor_id INTEGER,     action TEXT,     metadata TEXT,     created_at INTEGER );
CREATE TABLE events (     event_id INTEGER PRIMARY KEY AUTOINCREMENT,     name TEXT,     active INTEGER DEFAULT 0,     starts_at INTEGER,     ends_at INTEGER );
CREATE TABLE user_economy_state (user_id INTEGER PRIMARY KEY, last_daily_claim INTEGER DEFAULT 0, last_weekly_claim INTEGER DEFAULT 0, last_rob_attempt INTEGER DEFAULT 0, last_kill_attempt INTEGER DEFAULT 0, protected_until INTEGER DEFAULT 0, dead_until INTEGER DEFAULT 0);
CREATE TABLE migrations (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          version INTEGER UNIQUE,
          applied_at INTEGER
        );
CREATE TABLE message_store (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    message_id INTEGER,
    chat_id INTEGER,
    user_id INTEGER,
    username TEXT,
    text TEXT,
    created_at INTEGER,
    expires_at INTEGER
);
CREATE TABLE antispam_users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chat_id INTEGER,
    user_id INTEGER,
    enabled INTEGER DEFAULT 1
);
CREATE TABLE card_hands (
    match_id TEXT,
    user_id INTEGER,
    card_a TEXT,
    card_b TEXT,
    card_c TEXT,
    card_d TEXT,
    score INTEGER,
    strikes INTEGER,
    PRIMARY KEY(match_id, user_id)
);
CREATE TABLE card_state (
    match_id TEXT PRIMARY KEY,
    current_round INTEGER DEFAULT 1
);
CREATE TABLE card_disqualified (
    match_id TEXT,
    user_id INTEGER,
    PRIMARY KEY(match_id, user_id)
);
CREATE TABLE protections (
    chat_id INTEGER,
    type TEXT,
    enabled INTEGER DEFAULT 0,
    PRIMARY KEY(chat_id, type)
);
CREATE TABLE group_rules (
    chat_id INTEGER PRIMARY KEY,
    rules TEXT,
    updated_at INTEGER
);
CREATE TABLE group_settings (
    chat_id INTEGER,
    setting_key TEXT,
    value TEXT,
    PRIMARY KEY(chat_id, setting_key)
);
CREATE TABLE message_tracker (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chat_id INTEGER,
    user_id INTEGER,
    created_at INTEGER
);
CREATE TABLE join_tracker (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chat_id INTEGER,
    user_id INTEGER,
    joined_at INTEGER
);
CREATE TABLE economy_events (
    event_name TEXT PRIMARY KEY,
    enabled INTEGER,
    started_at INTEGER,
    expires_at INTEGER
);
CREATE TABLE settings (
    setting_key TEXT PRIMARY KEY,
    setting_value TEXT
);
CREATE TABLE profile (
    user_id INTEGER PRIMARY KEY,
    intro TEXT,
    title TEXT,
    reputation INTEGER DEFAULT 0,
    created_at INTEGER,
    updated_at INTEGER
);
CREATE TABLE profiles (
    user_id INTEGER PRIMARY KEY,
    intro TEXT,
    title TEXT,
    reputation INTEGER DEFAULT 0,
    created_at INTEGER,
    updated_at INTEGER
);
CREATE TABLE global_bans (
    user_id INTEGER PRIMARY KEY,
    username TEXT,
    reason TEXT,
    banned_by INTEGER,
    created_at INTEGER
);
CREATE TABLE scheduled_tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    task_name TEXT,
    run_at INTEGER,
    payload TEXT
);
CREATE TABLE search_cache (
    cache_key TEXT PRIMARY KEY,
    value TEXT,
    expires_at INTEGER
);
CREATE TABLE saved_messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chat_id INTEGER,
    message_id INTEGER,
    user_id INTEGER,
    text TEXT,
    created_at INTEGER
);
CREATE TABLE combat_status (
      user_id INTEGER PRIMARY KEY,
      status TEXT DEFAULT 'alive',
      protected_until INTEGER,
      dead_until INTEGER
    );
CREATE TABLE card_matches_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      match_id TEXT,
      data TEXT,
      created_at INTEGER
    );
CREATE TABLE schema_migrations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        version INTEGER NOT NULL,
        applied_at INTEGER NOT NULL
      );
CREATE TABLE scheduled_cleanup (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          table_name TEXT,
          row_id INTEGER,
          delete_at INTEGER
        );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_users_balance ON users(balance);
CREATE INDEX idx_users_status ON users(status);
CREATE INDEX idx_groups_chatid ON groups(chat_id);
CREATE INDEX idx_ai_memory_chatid ON ai_memory(chat_id);
CREATE INDEX idx_message_store_chatid ON message_store(chat_id);
CREATE INDEX idx_card_matches_chat ON card_matches(chat_id);
CREATE INDEX idx_card_players_match ON card_players(match_id);
CREATE INDEX idx_cooldowns_user_command ON cooldowns(user_id, command);
CREATE INDEX idx_protections_chat_type ON protections(chat_id, type);
CREATE INDEX idx_global_bans_user ON global_bans(user_id);
CREATE INDEX idx_message_tracker_chat_user ON message_tracker(chat_id, user_id);
CREATE INDEX idx_message_store_chat_created ON message_store(chat_id, created_at);
CREATE INDEX idx_ai_memory_chat_created ON ai_memory(chat_id, created_at);
CREATE INDEX idx_message_tracker_chat_user_time ON message_tracker(chat_id, user_id, created_at);
CREATE INDEX idx_join_tracker_chat_time ON join_tracker(chat_id, joined_at);
CREATE INDEX idx_transactions_sender ON transactions(sender_id);
CREATE INDEX idx_transactions_receiver ON transactions(receiver_id);
CREATE INDEX idx_card_matches_status_expires ON card_matches(status, expires_at);
CREATE INDEX idx_scheduled_posts_send_at ON scheduled_posts(send_at);
CREATE INDEX idx_message_store_chat on message_store(chat_id);
CREATE INDEX idx_ai_memory_chat on ai_memory(chat_id);
